import { isEmpty, isNil, round } from 'lodash';

export const ITEM_COLOR_DEFAULT = {
  COLOR: 255,
  COLOR_HEX: 'FF',
  ALPHA: 1,
  ALPHA_HEX: 'FF',
};

export function unHex(val = ITEM_COLOR_DEFAULT.COLOR_HEX) {
  const hex = isNil(val) || isEmpty(val) ? ITEM_COLOR_DEFAULT.COLOR_HEX : val;

  return parseInt(hex, 16);
}

export function unHexAlpha(val = ITEM_COLOR_DEFAULT.ALPHA_HEX) {
  const alpha = isNil(val) || isEmpty(val) ? ITEM_COLOR_DEFAULT.ALPHA_HEX : val;

  return round(unHex(alpha) / 255, 2);
}

/**
 * Splits the hex color to rgba object
 *
 * @param {string} hexColor - hex color to convert to rgba
 *
 * @returns {object} rgba - ex: { r: 244, b: 245, c: 133, a: 0.24 }
 */
export function hexToRgbaObject(hexColor = '') {
  const color =
    hexColor.charAt(0) === '#' ? hexColor.substring(1, 9) : hexColor;

  return {
    r: unHex(color.substring(0, 2)),
    g: unHex(color.substring(2, 4)),
    b: unHex(color.substring(4, 6)),
    a: unHexAlpha(color.substring(6, 8)),
  };
}

/**
 * Splits the hex color to an rgba value
 *
 * @param {string} hexColor - hex color to convert to rgba
 *
 * @return {string} rgba - ex: rgba(244, 245, 133, 0.24)
 *
 */
export function hexToRgba(hexColor = '') {
  const { r, g, b, a } = hexToRgbaObject(hexColor);

  return `rgba(${r}, ${g}, ${b}, ${a})`;
}

/**
 * For determining if the color of text should be white or black
 * based on the hexColor
 * Reference on computing the luminance:
 * https://www.w3.org/TR/WCAG20/#relativeluminancedef
 *
 * @param {string} hexColor - hex color to compare
 *
 * @returns {string} color - 'white' or 'black'
 *
 */
export function getTextColor(hexColor) {
  const { r, g, b, a } = hexToRgbaObject(hexColor);
  const [R, G, B] = [r / 255, g / 255, b / 255].map((c) => {
    if (c <= 0.03928) {
      return c / 12.92;
    }

    return Math.pow((c + 0.055) / 1.055, 2.4);
  });
  const luminance = 0.2126 * R + 0.7152 * G + 0.0722 * B;

  return luminance > 0.179 || a < 0.55 ? 'black' : 'white';
}
